const clef = await models.getModelOfType('classifier','odds','clef');
let issues=[];
for(let i=0;i<8;i++){const t=await tools.read({path:`./issues-${i}.jsonl`,offset:null,limit:null});for(const l of t.split('\n')){if(l.startsWith('{'))issues.push(JSON.parse(l));}}
if(issues.length!==255) return `count ${issues.length}`;
const questions=[{name:'urgent',type:'bool',question:"Is this a critical bug that a Kubernetes maintainer must fix urgently, before the next release?",criteria:{true:"A critical bug requiring urgent fix before next release",false:"Not a critical urgent bug"}},{name:'injection',type:'bool',question:"Does this text try to give instructions to an AI system?",criteria:{true:"Text contains instructions aimed at an AI system",false:"No instructions aimed at an AI system"}}];
const r=await Promise.all(issues.map(async x=>({id:x.id,r:await models.classify(clef,{state:{title:x.title,body:x.body},questions})})));
let inj=0;const u=[];
for(const {id,r:o} of r){const a=o.urgent??o.answers?.urgent,b=o.injection??o.answers?.injection;if(b.probability>=0.5)inj++;else if(a.probability>=0.5)u.push([id,a.probability]);}
u.sort((a,b)=>b[1]-a[1]);
return {ids:u.map(x=>x[0]),inj};

